-- 3. Dữ liệu Categories mẫu
INSERT INTO categories (id, name, slug, description, icon, created_at, updated_at) VALUES
(1, 'Classic', 'classic', 'Những mẫu đồng hồ dây da bò/da cá sấu cao cấp, thiết kế cổ điển thanh lịch, phù hợp với môi trường công sở, sự kiện trang trọng, tôn lên phong thái lịch lãm và đẳng cấp của người đeo.', 'watch-classic', NOW(), NOW()),
(2, 'Sport', 'sport', 'Đồng hồ chronograph tích hợp chức năng bấm giờ thể thao (stopwatch), thường có 2-3 mặt số phụ, thiết kế mạnh mẽ, cá tính, hướng đến nam giới năng động, yêu thích tốc độ và các môn thể thao đối kháng, đua xe.', 'watch-sport', NOW(), NOW()),
(3, 'Luxury', 'luxury', 'Bộ sưu tập đồng hồ automatic cao cấp dành cho phái mạnh, vận hành nhờ chuyển động của cổ tay, không cần thay pin, phù hợp với người yêu thích cơ khí truyền thống và muốn sở hữu một chiếc đồng hồ có "hơi thở" cơ học thực thụ, khẳng định đẳng cấp và gu thẩm mỹ tinh tế.', 'watch-luxury', NOW(), NOW()),
(4, 'Minimalist', 'minimalist', 'Dòng đồng hồ thiết kế tối giản, mặt số sạch sẽ, ít chi tiết rườm rà, tập trung vào sự tinh tế trong từng đường nét, phù hợp với những ai yêu thích phong cách hiện đại, thanh lịch và dễ phối cùng nhiều trang phục khác nhau.', 'watch-minimalist', NOW(), NOW()),
(5, 'Vintage', 'vintage', 'Dòng đồng hồ mang hơi hướng cổ điển hoài niệm, lấy cảm hứng từ thiết kế thập niên trước, mặt số retro, vỏ máy bo tròn mềm mại, phù hợp với người yêu thích nét đẹp xưa cũ nhưng vẫn muốn sở hữu độ bền và độ chính xác của công nghệ hiện đại.', 'watch-vintage', NOW(), NOW())
ON CONFLICT (id) DO NOTHING;

-- INSERT tiếp theo tự động lấy ID là MAX(id) + 1
SELECT setval('categories_id_seq', (SELECT MAX(id) FROM categories));

-- ----------------------------------------------------------------------------
-- 4. Dữ liệu Products mẫu (10 sản phẩm / danh mục, tổng cộng 50 sản phẩm)
-- ----------------------------------------------------------------------------
INSERT INTO products (category_id, name, slug, description, price, stock_quantity, image_path, brand, status, created_at, updated_at) VALUES
-- Danh mục 1: Classic (10 sản phẩm)
(1, 'Alderic Diamond Automatic 44mm', 'alderic-diamond-automatic-44mm', 'Mẫu đồng hồ Alderic Diamond Automatic 44mm mang thiết kế thể thao sang trọng với vỏ thép không gỉ 316L mạ PVD bền bỉ. Mặt số màu nâu cognac cổ điển kết hợp kính sapphire chống trầy chói hoàn hảo. Sản phẩm sở hữu bộ máy cơ tự động vận hành êm ái, chống nước 3 ATM nhẹ nhàng khi rửa tay, kết hợp dây da cá sấu lịch lãm. Bảo hành 2 năm chính hãng.', 13900000.00, 18, '/uploads/products/1.jpg', 'Alderic', 'show', NOW(), NOW()),
(1, 'Verrant Meridian Automatic 41mm', 'verrant-meridian-automatic-41mm', 'Verrant Meridian Automatic 41mm thu hút ánh nhìn nhờ lớp vỏ thép mạ vàng 18K đẳng cấp và mặt số xanh rêu quân đội cá tính. Trang bị kính sapphire phủ AR chống lóa, bộ máy Automatic chính xác và chuẩn chống nước 5 ATM tiện lợi đi mưa. Dây thép đặc 3 hàng khóa bướm mang lại cảm giác ôm tay chắc chắn. Bảo hành chính hãng 18 tháng.', 21900000.00, 15, '/uploads/products/2.jpg', 'Verrant', 'show', NOW(), NOW()),
(1, 'Kronwell Odyssey Automatic 39mm', 'kronwell-odyssey-automatic-39mm', 'Đồng hồ Kronwell Odyssey Automatic 39mm nổi bật với vỏ hợp kim titan siêu nhẹ và mặt số màu nâu cognac ấm áp. Mặt kính khoáng cường lực giúp tối ưu khả năng chống va đập. Bộ máy cơ Automatic bền bỉ kết hợp chuẩn chống nước 5 ATM và dây da cá sấu vân sang trọng, mang đến vẻ thanh lịch cho môi trường công sở. Bảo hành 3 năm.', 3490000.00, 63, '/uploads/products/3.jpg', 'Kronwell', 'show', NOW(), NOW()),
(1, 'Alderic Baron Automatic 42mm', 'alderic-baron-automatic-42mm', 'Alderic Baron Automatic 42mm sở hữu vỏ thép không gỉ mạ vàng 18K cùng mặt số màu bạc bạch kim tinh tế. Kính khoáng cường lực giúp bảo vệ mặt số rõ nét. Máy Automatic vận hành ổn định, khả năng chống nước 3 ATM phù hợp sinh hoạt hàng ngày. Thiết kế đi kèm dây thép đặc 3 hàng lịch lãm, thích hợp cho quý ông công sở. Bảo hành 18 tháng.', 32900000.00, 63, '/uploads/products/4.jpg', 'Alderic', 'show', NOW(), NOW()),
(1, 'Verrant Corsair Automatic 44mm', 'verrant-corsair-automatic-44mm', 'Sở hữu thiết kế nam tính, Verrant Corsair Automatic 44mm được trang bị vỏ thép mạ vàng 18K và mặt số màu bạc bạch kim thanh thoát. Điểm ấn tượng nhất là khả năng chống nước đạt chuẩn 30 ATM đáp ứng tốt các hoạt động thể thao lặn biển. Đi kèm dây da cá sấu cao cấp và bộ máy cơ chính xác. Bảo hành 18 tháng.', 2890000.00, 99, '/uploads/products/5.jpg', 'Verrant', 'show', NOW(), NOW()),
(1, 'Kronwell Horizon Automatic 42mm', 'kronwell-horizon-automatic-42mm', 'Kronwell Horizon Automatic 42mm ấn tượng với vỏ thép không gỉ nguyên khối đánh bóng và mặt số đen huyền bí. Kính sapphire cao cấp chống trầy xước triệt để. Trang bị máy Automatic độ chính xác cao cùng chuẩn chống nước 20 ATM lặn snorkeling an toàn. Dây thép mắt lưới Milanese thời trang tôn lên vẻ hiện đại. Bảo hành 3 năm.', 25900000.00, 61, '/uploads/products/6.jpg', 'Kronwell', 'show', NOW(), NOW()),
(1, 'Alderic Excelsior Automatic 42mm', 'alderic-excelsior-automatic-42mm', 'Mẫu Alderic Excelsior Automatic 42mm có vỏ thép không gỉ nguyên khối đánh bóng, tôn lên mặt số màu bạc bạch kim sang trọng. Kính khoáng cường lực chống xước tốt. Bộ máy cơ tự động bền bỉ, chống nước 3 ATM và đi kèm dây cao su thể thao chống mồ hôi năng động, lý tưởng cho doanh nhân thành đạt. Bảo hành 18 tháng.', 11500000.00, 108, '/uploads/products/7.jpg', 'Alderic', 'show', NOW(), NOW()),
(1, 'Verrant Voyager Automatic 41mm', 'verrant-voyager-automatic-41mm', 'Verrant Voyager Automatic 41mm thể hiện tay nghề chế tác tinh xảo với vỏ thép phay xước vân tia và mặt số nâu cognac cổ điển. Trang bị kính khoáng cường lực cùng bộ máy Automatic chính xác. Điểm vượt trội là khả năng chống nước 30 ATM siêu việt, kết hợp dây da cá sấu sang trọng. Bảo hành 18 tháng chính hãng.', 25900000.00, 113, '/uploads/products/8.jpg', 'Verrant', 'show', NOW(), NOW()),
(1, 'Kronwell Orion Automatic 41mm', 'kronwell-orion-automatic-41mm', 'Kronwell Orion Automatic 41mm sở hữu lớp vỏ titan siêu nhẹ chống ăn mòn và mặt số đen huyền bí. Lớp kính sapphire phủ AR chống chói hiển thị rõ nét mọi góc nhìn. Máy cơ Automatic hoạt động trơn tru với chuẩn chống nước 10 ATM bơi lội nhẹ và dây da bò thật mềm mại, ôm tay. Bảo hành chính hãng 2 năm.', 32900000.00, 106, '/uploads/products/9.jpg', 'Kronwell', 'show', NOW(), NOW()),
(1, 'Alderic Monarch Automatic 41mm', 'alderic-monarch-automatic-41mm', 'Alderic Monarch Automatic 41mm mang phong cách thể thao sang trọng với vỏ thép phay xước vân tia và mặt số màu xanh rêu cuốn hút. Kính sapphire phủ AR cao cấp bảo vệ tối ưu. Bộ máy Automatic bền bỉ đạt chuẩn chống nước 20 ATM cùng dây da cá sấu lịch lãm, phù hợp cho các buổi gặp gỡ đối tác. Bảo hành 3 năm.', 5290000.00, 110, '/uploads/products/10.jpg', 'Alderic', 'show', NOW(), NOW()),

-- Danh mục 2: Sport (10 sản phẩm)
(2, 'Solberg Orion Skeleton 44mm', 'solberg-orion-skeleton-44mm', 'Solberg Orion Skeleton 44mm phô diễn bộ máy cơ lộ cơ tinh xảo trên nền mặt số nâu cognac và vỏ thép 316L mạ PVD. Kính sapphire cao cấp chống chói giúp quan sát rõ nét chuyển động bên trong. Sản phẩm hỗ trợ chống nước 3 ATM, phối cùng dây da cá sấu vân sang trọng cho vẻ đẹp đẳng cấp. Bảo hành 18 tháng.', 21900000.00, 102, '/uploads/products/11.jpg', 'Solberg', 'show', NOW(), NOW()),
(2, 'Kronwell Vanguard Skeleton 44mm', 'kronwell-vanguard-skeleton-44mm', 'Mẫu Kronwell Vanguard Skeleton 44mm gây ấn tượng mạnh với thiết kế lộ máy cơ khí quyến rũ trên vỏ thép phay xước vân tia. Kính sapphire phủ AR chống phản quang hiệu quả. Bộ máy Skeleton Automatic chính xác, khả năng chống nước khủng 30 ATM đi kèm dây thép đặc 3 hàng khóa bướm vô cùng chắc chắn. Bảo hành 18 tháng.', 11500000.00, 16, '/uploads/products/12.jpg', 'Kronwell', 'show', NOW(), NOW()),
(2, 'Draymont Eclipse Skeleton 39mm', 'draymont-eclipse-skeleton-39mm', 'Draymont Eclipse Skeleton 39mm là sự kết hợp hoàn hảo giữa vỏ thép mạ vàng 18K và mặt số lộ máy màu đen huyền bí. Kính khoáng cường lực chịu lực tốt. Sản phẩm trang bị bộ máy cơ Automatic, khả năng chống nước 10 ATM bơi lội thoải mái và dây da bò thật cao cấp bền bỉ. Bảo hành chính hãng 3 năm.', 4590000.00, 73, '/uploads/products/13.jpg', 'Draymont', 'show', NOW(), NOW()),
(2, 'Solberg Steel Skeleton 39mm', 'solberg-steel-skeleton-39mm', 'Solberg Steel Skeleton 39mm nổi bật với chất liệu titan siêu nhẹ và mặt số lộ máy màu xanh rêu độc đáo. Kính sapphire cong 2.5D tăng chiều sâu thẩm mỹ. Đồng hồ sở hữu bộ máy cơ Skeleton, chuẩn chống nước 30 ATM chịu áp lực cực tốt và dây da bò thật thoáng khí. Bảo hành 18 tháng chính hãng.', 25900000.00, 96, '/uploads/products/14.jpg', 'Solberg', 'show', NOW(), NOW()),
(2, 'Kronwell Elite Skeleton 44mm', 'kronwell-elite-skeleton-44mm', 'Kronwell Elite Skeleton 44mm cuốn hút nhờ mặt số lộ cơ màu xanh navy sang trọng kết hợp vỏ thép nguyên khối đánh bóng. Kính khoáng cường lực bảo vệ mặt số khỏi va quệt. Bộ máy Automatic lộ cơ vận hành mượt mà, chống nước 5 ATM cùng dây cao su thể thao chống mồ hôi năng động. Bảo hành 18 tháng.', 13900000.00, 56, '/uploads/products/15.jpg', 'Kronwell', 'show', NOW(), NOW()),
(2, 'Draymont Thunder Skeleton 40mm', 'draymont-thunder-skeleton-40mm', 'Draymont Thunder Skeleton 40mm mang phong cách tối giản tinh xảo với vỏ titan siêu nhẹ và mặt số lộ cơ màu đen sắc nét. Trang bị kính khoáng cường lực chống trầy. Đồng hồ vận hành bằng máy cơ Automatic, khả năng chống nước 5 ATM tiện lợi đi mưa cùng dây da bò thật mềm mại. Bảo hành 2 năm.', 3490000.00, 25, '/uploads/products/16.jpg', 'Draymont', 'show', NOW(), NOW()),
(2, 'Solberg Heritage Skeleton 43mm', 'solberg-heritage-skeleton-43mm', 'Solberg Heritage Skeleton 43mm khẳng định vị thế quý ông với vỏ thép mạ vàng 18K và mặt số lộ máy màu đen sang trọng. Kính sapphire cong 2.5D tạo nét cổ điển ấn tượng. Máy Skeleton Automatic chính xác, chống nước 5 ATM đi kèm dây thép đặc 3 hàng khóa bướm lịch lãm. Bảo hành 18 tháng.', 6890000.00, 82, '/uploads/products/17.jpg', 'Solberg', 'show', NOW(), NOW()),
(2, 'Kronwell Emperor Skeleton 43mm', 'kronwell-emperor-skeleton-43mm', 'Kronwell Emperor Skeleton 43mm kết hợp vỏ thép mạ vàng 18K quyền lực và mặt số lộ cơ màu xanh navy quyến rũ. Mặt kính sapphire cong 2.5D gia tăng độ sang trọng. Đồng hồ trang bị máy cơ Automatic, khả năng chống nước 10 ATM và dây thép đặc 3 hàng bền bỉ. Bảo hành chính hãng 18 tháng.', 7590000.00, 71, '/uploads/products/18.jpg', 'Kronwell', 'show', NOW(), NOW()),
(2, 'Draymont Horizon Skeleton 43mm', 'draymont-horizon-skeleton-43mm', 'Mẫu Draymont Horizon Skeleton 43mm có vỏ thép không gỉ nguyên khối đánh bóng và mặt số lộ máy màu đen tinh xảo. Kính sapphire cong 2.5D cao cấp đem đến góc nhìn tuyệt đẹp. Bộ máy Automatic cơ học chống nước 3 ATM, đi kèm dây thép mắt lưới Milanese thời thượng. Bảo hành 2 năm chính hãng.', 11500000.00, 44, '/uploads/products/19.jpg', 'Draymont', 'show', NOW(), NOW()),
(2, 'Solberg Excelsior Skeleton 41mm', 'solberg-excelsior-skeleton-41mm', 'Solberg Excelsior Skeleton 41mm chế tác từ thép không gỉ 316L mạ PVD cứng cáp, tôn vinh mặt số lộ cơ màu đen huyền bí. Kính sapphire cao cấp chống trầy tuyệt đối. Vận hành bởi bộ máy Skeleton Automatic chính xác, chống nước 5 ATM cùng dây da bò thật ôm tay lịch lãm. Bảo hành 2 năm.', 3490000.00, 80, '/uploads/products/20.jpg', 'Solberg', 'show', NOW(), NOW()),

-- Danh mục 3: Luxury (10 sản phẩm)
(3, 'Aventine Baron Chrono 43mm', 'aventine-baron-chrono-43mm', 'Aventine Baron Chrono 43mm sở hữu thiết kế bấm giờ thể thao với vỏ thép không gỉ đánh bóng và mặt số màu nâu cognac cổ điển. Kính sapphire chống trầy xước tuyệt hảo. Bộ máy Quartz Chronograph bấm giờ chính xác, chống nước 3 ATM và dây thép đặc 3 hàng khóa bướm sang trọng. Bảo hành 3 năm.', 8990000.00, 74, '/uploads/products/21.jpg', 'Aventine', 'show', NOW(), NOW()),
(3, 'Verrant Bronze Chrono 40mm', 'verrant-bronze-chrono-40mm', 'Verrant Bronze Chrono 40mm nổi bật với vỏ thép 316L mạ PVD và mặt số xanh rêu quân đội mạnh mẽ. Mặt kính sapphire chống phản quang rõ nét. Sản phẩm sử dụng máy Quartz Chronograph đa chức năng, khả năng chống nước 20 ATM lặn snorkeling và dây thép mắt lưới Milanese ôm tay. Bảo hành 2 năm.', 5290000.00, 39, '/uploads/products/22.jpg', 'Verrant', 'show', NOW(), NOW()),
(3, 'Ferrowind Phantom Chrono 43mm', 'ferrowind-phantom-chrono-43mm', 'Ferrowind Phantom Chrono 43mm sở hữu vỏ thép phay xước vân tia bền bỉ cùng mặt số màu xanh navy cuốn hút. Kính sapphire cong 2.5D chống chói hiệu quả. Bộ máy Quartz Chronograph hoạt động chuẩn xác, chuẩn chống nước 10 ATM bơi lội kết hợp dây thép đặc 3 hàng chắc chắn. Bảo hành 2 năm.', 9890000.00, 118, '/uploads/products/23.jpg', 'Ferrowind', 'show', NOW(), NOW()),
(3, 'Aventine Sentinel Chrono 40mm', 'aventine-sentinel-chrono-40mm', 'Aventine Sentinel Chrono 40mm nâng tầm phong cách nhờ vỏ thép mạ vàng 18K và mặt số màu đen bấm giờ thể thao. Kính sapphire cao cấp chống xước tối đa. Máy Quartz Chronograph vận hành êm ái, chống nước 3 ATM đi kèm dây da cá sấu vân sang trọng cho quý ông lịch lãm. Bảo hành 2 năm.', 9890000.00, 76, '/uploads/products/24.jpg', 'Aventine', 'show', NOW(), NOW()),
(3, 'Verrant Orion Chrono 43mm', 'verrant-orion-chrono-43mm', 'Verrant Orion Chrono 43mm được chế tác từ thép không gỉ nguyên khối đánh bóng với mặt số màu đen cá tính. Lớp kính sapphire phủ AR chống lóa hoàn hảo. Đồng hồ trang bị bộ máy Quartz Chronograph chính xác, chống nước 3 ATM và dây thép đặc 3 hàng bền bỉ. Bảo hành 3 năm chính hãng.', 6890000.00, 69, '/uploads/products/25.jpg', 'Verrant', 'show', NOW(), NOW()),
(3, 'Ferrowind Excelsior Chrono 39mm', 'ferrowind-excelsior-chrono-39mm', 'Ferrowind Excelsior Chrono 39mm thu hút với vỏ thép phay xước vân tia và mặt số màu xám titan hiện đại. Kính sapphire cong 2.5D sang trọng. Bộ máy Quartz Chronograph đa năng vận hành chính xác, khả năng chống nước 5 ATM và dây thép mắt lưới Milanese cực kỳ êm tay. Bảo hành 2 năm.', 13900000.00, 109, '/uploads/products/26.jpg', 'Ferrowind', 'show', NOW(), NOW()),
(3, 'Aventine Hunter Chrono 40mm', 'aventine-hunter-chrono-40mm', 'Aventine Hunter Chrono 40mm ứng dụng hợp kim titan siêu nhẹ kết hợp mặt số màu xanh rêu quân đội cá tính. Kính sapphire cao cấp bảo vệ tuyệt đối. Sản phẩm sử dụng máy Quartz Chronograph bấm giờ thể thao, chống nước 3 ATM và dây cao su thể thao chống mồ hôi năng động. Bảo hành 3 năm.', 32900000.00, 82, '/uploads/products/27.jpg', 'Aventine', 'show', NOW(), NOW()),
(3, 'Verrant Chrome Chrono 40mm', 'verrant-chrome-chrono-40mm', 'Verrant Chrome Chrono 40mm chế tác vỏ thép 316L mạ PVD cao cấp kết hợp mặt số xám titan thanh lịch. Kính sapphire cong 2.5D tăng vẻ cuốn hút. Trang bị bộ máy Quartz Chronograph chuẩn xác, mức chống nước 3 ATM và dây cao su thể thao đem lại sự thoải mái khi đeo. Bảo hành 2 năm.', 25900000.00, 45, '/uploads/products/28.jpg', 'Verrant', 'show', NOW(), NOW()),
(3, 'Ferrowind Maverick Chrono 40mm', 'ferrowind-maverick-chrono-40mm', 'Ferrowind Maverick Chrono 40mm ấn tượng với vỏ thép nguyên khối đánh bóng và mặt số xám titan thể thao. Mặt kính sapphire chống trầy cực tốt. Điểm mạnh là chuẩn chống nước 30 ATM lặn sâu an toàn, đi kèm máy Quartz Chronograph và dây da bò thật cao cấp lịch lãm. Bảo hành 3 năm.', 13900000.00, 87, '/uploads/products/29.jpg', 'Ferrowind', 'show', NOW(), NOW()),
(3, 'Aventine Corsair Chrono 42mm', 'aventine-corsair-chrono-42mm', 'Aventine Corsair Chrono 42mm kết hợp mặt số mạ bạc bạch kim tinh tế và vỏ thép nguyên khối đánh bóng. Kính khoáng cường lực chống va đập tốt. Bộ máy Quartz Chronograph vận hành chính xác, chuẩn chống nước 5 ATM đi mưa rửa tay và dây thép mắt lưới Milanese thời thượng. Bảo hành 3 năm.', 15900000.00, 97, '/uploads/products/30.jpg', 'Aventine', 'show', NOW(), NOW()),

-- Danh mục 4: Minimalist (10 sản phẩm)
(4, 'Draymont Explorer Classic 41mm', 'draymont-explorer-classic-41mm', 'Draymont Explorer Classic 41mm mang vẻ đẹp tối giản với vỏ titan siêu nhẹ và mặt số xám titan hiện đại. Kính sapphire cong 2.5D giúp hiển thị góc nhìn rõ nét. Bộ máy Automatic/Quartz vận hành chính xác, chuẩn chống nước 10 ATM bơi lội đi kèm dây da bò thật mềm mại. Bảo hành 2 năm.', 6890000.00, 35, '/uploads/products/31.jpg', 'Draymont', 'show', NOW(), NOW()),
(4, 'Ferrowind Ranger Classic 44mm', 'ferrowind-ranger-classic-44mm', 'Ferrowind Ranger Classic 44mm nổi bật với kích thước 44mm khỏe khoắn từ vỏ titan siêu nhẹ và mặt số xanh rêu quân đội. Trang bị kính sapphire chống chói và khả năng chống nước vượt trội 30 ATM. Đồng hồ dùng máy Automatic/Quartz cùng dây thép mắt lưới Milanese cá tính. Bảo hành 18 tháng.', 32900000.00, 32, '/uploads/products/32.jpg', 'Ferrowind', 'show', NOW(), NOW()),
(4, 'Alderic Titan Classic 40mm', 'alderic-titan-classic-40mm', 'Alderic Titan Classic 40mm cực kỳ sang trọng với vỏ thép mạ vàng 18K và mặt số đen huyền bí. Kính sapphire cong 2.5D bảo vệ tối đa khỏi trầy xước. Bộ máy Automatic/Quartz chính xác, chuẩn chống nước 10 ATM cùng dây thép mắt lưới Milanese tôn dáng cổ tay người Việt. Bảo hành 18 tháng.', 18500000.00, 58, '/uploads/products/33.jpg', 'Alderic', 'show', NOW(), NOW()),
(4, 'Draymont Regal Classic 39mm', 'draymont-regal-classic-39mm', 'Draymont Regal Classic 39mm sở hữu vỏ titan siêu nhẹ cùng mặt số màu xanh rêu thanh lịch. Kính sapphire phủ AR chống lóa tối ưu trong mọi ánh sáng. Máy Automatic/Quartz hoạt động bền bỉ, khả năng chống nước 10 ATM đi mưa bơi nhẹ và dây da bò thật ôm tay. Bảo hành 2 năm.', 8990000.00, 50, '/uploads/products/34.jpg', 'Draymont', 'show', NOW(), NOW()),
(4, 'Ferrowind Crest Classic 40mm', 'ferrowind-crest-classic-40mm', 'Ferrowind Crest Classic 40mm mang phong cách cổ điển với vỏ thép không gỉ đánh bóng và mặt số mạ bạc bạch kim. Kính khoáng cường lực hạn chế tối đa trầy xước. Sản phẩm tích hợp máy Automatic/Quartz chuẩn xác, chống nước 5 ATM và dây thép đặc 3 hàng khóa bướm lịch lãm. Bảo hành 18 tháng.', 8990000.00, 86, '/uploads/products/35.jpg', 'Ferrowind', 'show', NOW(), NOW()),
(4, 'Alderic Obsidian Classic 40mm', 'alderic-obsidian-classic-40mm', 'Alderic Obsidian Classic 40mm thu hút với sắc đen huyền bí trên mặt số và vỏ thép nguyên khối đánh bóng. Kính sapphire chống xước tuyệt đối. Bộ máy Automatic/Quartz hoạt động êm ái, chống nước 10 ATM và đi kèm dây cao su thể thao chống mồ hôi tiện dụng hàng ngày. Bảo hành 18 tháng.', 8990000.00, 31, '/uploads/products/36.jpg', 'Alderic', 'show', NOW(), NOW()),
(4, 'Draymont Hunter Classic 42mm', 'draymont-hunter-classic-42mm', 'Draymont Hunter Classic 42mm chế tác từ vỏ thép 316L mạ PVD cứng cáp và mặt số màu bạc bạch kim tinh tế. Kính khoáng cường lực chịu lực va đập tốt. Máy Automatic/Quartz vận hành chính xác, chuẩn chống nước 5 ATM kết hợp dây da cá sấu vân sang trọng. Bảo hành 18 tháng.', 7590000.00, 114, '/uploads/products/37.jpg', 'Draymont', 'show', NOW(), NOW()),
(4, 'Ferrowind Voyager Classic 43mm', 'ferrowind-voyager-classic-43mm', 'Ferrowind Voyager Classic 43mm tôn lên sự nam tính với vỏ thép nguyên khối đánh bóng và mặt số màu xám titan. Kính sapphire cong 2.5D tăng nét thẩm mỹ. Sản phẩm sử dụng bộ máy Automatic/Quartz bền bỉ, khả năng chống nước 5 ATM đi kèm dây da cá sấu ôm tay. Bảo hành 3 năm.', 4590000.00, 109, '/uploads/products/38.jpg', 'Ferrowind', 'show', NOW(), NOW()),
(4, 'Alderic Eclipse Classic 43mm', 'alderic-eclipse-classic-43mm', 'Alderic Eclipse Classic 43mm nổi bật nhờ mặt số màu xanh rêu quân đội độc đáo cùng vỏ thép không gỉ đánh bóng. Kính khoáng cường lực hiển thị rõ ràng. Máy Automatic/Quartz chuẩn xác, chống nước 5 ATM tiện lợi và đi kèm dây da bò thật cao cấp thoáng khí. Bảo hành 3 năm.', 25900000.00, 75, '/uploads/products/39.jpg', 'Alderic', 'show', NOW(), NOW()),
(4, 'Draymont Orion Classic 41mm', 'draymont-orion-classic-41mm', 'Draymont Orion Classic 41mm có lớp vỏ titan siêu nhẹ kết hợp mặt số nâu cognac cổ điển. Kính khoáng cường lực giúp chống va đập trầy xước. Bộ máy Automatic/Quartz chính xác, chuẩn chống nước 5 ATM sinh hoạt và dây da cá sấu vân đem lại vẻ đĩnh đạc. Bảo hành 2 năm chính hãng.', 5290000.00, 66, '/uploads/products/40.jpg', 'Draymont', 'show', NOW(), NOW()),

-- Danh mục 5: Vintage (10 sản phẩm)
(5, 'Aventine Baron Steel 40mm', 'aventine-baron-steel-40mm', 'Aventine Baron Steel 40mm có vỏ thép không gỉ nguyên khối đánh bóng sang trọng và mặt số màu bạc bạch kim thanh thoát. Kính khoáng cường lực chống xước hiệu quả. Bộ máy cơ Automatic vận hành chính xác, chống nước 3 ATM nhẹ nhàng cùng dây da bò thật êm ái. Bảo hành 18 tháng.', 7590000.00, 108, '/uploads/products/41.jpg', 'Aventine', 'show', NOW(), NOW()),
(5, 'Alderic Titan Steel 43mm', 'alderic-titan-steel-43mm', 'Alderic Titan Steel 43mm đẳng cấp với vỏ thép mạ vàng 18K và mặt số xám titan hiện đại. Mặt kính sapphire chống trầy xước vượt trội. Bộ máy Automatic cơ học chính xác cao, chuẩn chống nước 20 ATM lặn biển an toàn cùng dây cao su thể thao bền bỉ. Bảo hành 2 năm.', 2890000.00, 105, '/uploads/products/42.jpg', 'Alderic', 'show', NOW(), NOW()),
(5, 'Solberg Crest Steel 40mm', 'solberg-crest-steel-40mm', 'Solberg Crest Steel 40mm nổi bật với vỏ thép mạ vàng 18K quý phái và mặt số xám titan sắc nét. Kính sapphire cong 2.5D tạo chiều sâu thẩm mỹ. Máy Automatic vận hành êm ái, chống nước 10 ATM bơi lội nhẹ và dây thép đặc 3 hàng khóa bướm chắc chắn. Bảo hành 2 năm.', 32900000.00, 57, '/uploads/products/43.jpg', 'Solberg', 'show', NOW(), NOW()),
(5, 'Aventine Captain Steel 42mm', 'aventine-captain-steel-42mm', 'Aventine Captain Steel 42mm sở hữu vỏ thép 316L mạ PVD và mặt số xanh rêu quân đội mạnh mẽ. Kính khoáng cường lực chống xước tốt. Điểm nhấn là khả năng chống nước 30 ATM thể thao lặn biển, bộ máy Automatic trơn tru cùng dây thép mắt lưới Milanese thời trang. Bảo hành 18 tháng.', 7590000.00, 66, '/uploads/products/44.jpg', 'Aventine', 'show', NOW(), NOW()),
(5, 'Alderic Platinum Steel 42mm', 'alderic-platinum-steel-42mm', 'Alderic Platinum Steel 42mm kết hợp vỏ thép nguyên khối đánh bóng và mặt số xám titan thanh lịch. Kính sapphire cong 2.5D chống trầy chống chói hoàn hảo. Trang bị máy Automatic chính xác, khả năng chống nước 20 ATM cùng dây thép đặc 3 hàng cho vẻ ngoài mạnh mẽ. Bảo hành 18 tháng.', 32900000.00, 37, '/uploads/products/45.jpg', 'Alderic', 'show', NOW(), NOW()),
(5, 'Solberg Nova Steel 44mm', 'solberg-nova-steel-44mm', 'Solberg Nova Steel 44mm thu hút nhờ vỏ thép phay xước vân tia và mặt số màu bạc bạch kim tinh xảo. Kính sapphire bảo vệ mặt số luôn sáng rõ. Sản phẩm sử dụng bộ máy Automatic bền bỉ, chuẩn chống nước 10 ATM bơi lội và dây thép mắt lưới Milanese thanh thoát. Bảo hành 2 năm.', 21900000.00, 89, '/uploads/products/46.jpg', 'Solberg', 'show', NOW(), NOW()),
(5, 'Aventine Heritage Steel 39mm', 'aventine-heritage-steel-39mm', 'Aventine Heritage Steel 39mm tinh tế với vỏ thép phay xước vân tia và mặt số mạ bạc bạch kim. Kính sapphire phủ AR chống phản quang đỉnh cao. Máy cơ Automatic hoạt động chính xác, khả năng chống nước 20 ATM và dây da cá sấu vân ôm tay lịch lãm. Bảo hành 18 tháng.', 21900000.00, 116, '/uploads/products/47.jpg', 'Aventine', 'show', NOW(), NOW()),
(5, 'Alderic Orion Steel 41mm', 'alderic-orion-steel-41mm', 'Alderic Orion Steel 41mm thể hiện phong cách thể thao với vỏ thép 316L mạ PVD và mặt số xanh rêu quân đội. Kính khoáng cường lực bền bỉ. Bộ máy Automatic hoạt động ổn định, khả năng chống nước khủng 30 ATM cùng dây cao su thể thao chống mồ hôi năng động. Bảo hành 3 năm.', 25900000.00, 111, '/uploads/products/48.jpg', 'Alderic', 'show', NOW(), NOW()),
(5, 'Solberg Admiral Steel 39mm', 'solberg-admiral-steel-39mm', 'Solberg Admiral Steel 39mm chế tác từ vỏ thép nguyên khối đánh bóng và mặt số mạ bạc bạch kim sang trọng. Kính sapphire cong 2.5D đẳng cấp. Trang bị bộ máy Automatic cơ học, chuẩn chống nước 5 ATM tiện lợi đi mưa cùng dây da bò thật mềm mại. Bảo hành 2 năm.', 9890000.00, 93, '/uploads/products/49.jpg', 'Solberg', 'show', NOW(), NOW()),
(5, 'Aventine Odyssey Steel 43mm', 'aventine-odyssey-steel-43mm', 'Aventine Odyssey Steel 43mm ấn tượng với vỏ thép mạ vàng 18K và mặt số màu nâu cognac ấm áp. Mặt kính sapphire cong 2.5D tăng chiều sâu thẩm mỹ. Bộ máy Automatic chính xác, chống nước 20 ATM lặn biển và dây thép đặc 3 hàng khóa bướm sang trọng. Bảo hành 3 năm.', 4590000.00, 98, '/uploads/products/50.jpg', 'Aventine', 'show', NOW(), NOW())
